-- Paste ALL of this into Supabase -> SQL Editor -> New query -> Run, once. It is one transaction: if anything
-- fails, nothing is changed. Confirm the 'destructive operation' warning (it comes from 'create or replace' and
-- 'drop ... if exists' lines; no data is deleted). The checks at the end fail the whole paste if a piece is missing.
-- Generated by scripts/build-production-sql.mjs from supabase/migrations/20261012000040_more_categories.sql .. 20261012000040_more_categories.sql;
-- do not edit by hand.
begin;

-- Run the new categories script (docs/launch/new-categories-production.sql) first: this stops (changing nothing) if it hasn't been.
do $requires$
begin
  if not exists (select 1 from supabase_migrations.schema_migrations where version = '20261012000039') then
    raise exception 'Run the new categories script (docs/launch/new-categories-production.sql) first: migration 20261012000039 is not recorded';
  end if;
end
$requires$;

-- ==== 20261012000040_more_categories.sql
-- More trades requested by the owner: estate agents (Moving & waste, where people moving house look), accountants (a
-- new Business & finance group), travel agents (the Transport group, renamed Travel & transport), window tinting,
-- CCTV & security, and wedding & event venues; MOT and Mechanic get clearer names. Each comes with the check that
-- matters: estate agents must belong to a redress scheme (Consumers, Estate Agents and Redress Act 2007), anyone can
-- call themselves an accountant, flights and package holidays should be ATOL protected, front window tints have legal
-- limits, MOTs need a DVSA-approved centre, and cameras that see past your boundary bring data protection duties.
-- Idempotent: safe to run again.
insert into public.category_groups (name, slug, sort, asks_tidy) values ('Business & finance', 'business-finance', 8, false)
on conflict (slug) do nothing;
update public.category_groups set name = 'Travel & transport' where slug = 'transport';

insert into public.categories (group_id, slug, name, requirement, guidance_note)
select g.id, v.slug, v.name, 'none'::public.category_requirement, v.note
from (values
  ('moving-waste', 'estate-agents', 'Estate agents', 'Estate agents must belong to a government-approved redress scheme (The Property Ombudsman or the Property Redress Scheme). Ask which one before you sign.'),
  ('business-finance', 'accountants', 'Accountants', 'Anyone can call themselves an accountant. Look for membership of ICAEW, ACCA, CIMA or AAT.'),
  ('transport', 'travel-agents', 'Travel agents', 'For flights and package holidays (Umrah and Hajj packages included), check the booking is ATOL protected. ABTA membership is a good sign too.'),
  ('vehicles', 'window-tinting', 'Window tinting', 'The windscreen must let through at least 75% of light and the front side windows at least 70%. Darker tints there can mean a fine or a failed MOT; rear windows have no limit.'),
  ('home-trades', 'cctv-security', 'CCTV & security', 'For alarms, NSI or SSAIB approval is a good sign. If cameras will see past your boundary (the street or a neighbour''s home), the footage comes under data protection law: ask the installer where to point them.'),
  ('events-occasions', 'venues', 'Wedding & event venues', null)
) as v(grp, slug, name, note)
join public.category_groups g on g.slug = v.grp
on conflict (slug) do nothing;

update public.categories
set name = 'MOT test', guidance_note = 'MOTs can only be done at a DVSA-approved test centre: look for the blue sign with three white triangles.'
where slug = 'mot';
update public.categories set name = 'Mechanic & car servicing' where slug = 'mechanic';

insert into supabase_migrations.schema_migrations (version, name) values ('20261012000040', 'more_categories') on conflict do nothing;

-- ==================================================================== verification
-- Fails (and so rolls back everything above) if any piece is missing.
do $verify$
begin
  if (select count(*) from public.categories c join public.category_groups g on g.id = c.group_id
      where c.active and ((c.slug = 'estate-agents' and g.slug = 'moving-waste')
                       or (c.slug = 'accountants' and g.slug = 'business-finance')
                       or (c.slug = 'travel-agents' and g.slug = 'transport')
                       or (c.slug = 'window-tinting' and g.slug = 'vehicles')
                       or (c.slug = 'cctv-security' and g.slug = 'home-trades')
                       or (c.slug = 'venues' and g.slug = 'events-occasions'))) <> 6 then
    raise exception 'More categories check failed: one of the six new trades is missing';
  end if;
  if not exists (select 1 from public.categories where slug = 'mot' and name = 'MOT test')
     or not exists (select 1 from public.categories where slug = 'mechanic' and name = 'Mechanic & car servicing') then
    raise exception 'More categories check failed: MOT test or Mechanic & car servicing was not renamed';
  end if;
  if not exists (select 1 from public.category_groups where slug = 'transport' and name = 'Travel & transport') then
    raise exception 'More categories check failed: the Transport group was not renamed';
  end if;
end
$verify$;

commit;

select 'More categories applied' as result,
       (select count(*) from supabase_migrations.schema_migrations where version in ('20261012000040')) as migrations_recorded;
